INSERT INTO `audit_logs` (`id`, `user_id`, `action`, `model_type`, `model_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('68', '1', 'update', 'App\\Models\\AboutPage', '1', '{\"id\":1,\"key\":\"main\",\"hero_contact_url\":\"\\/contact\",\"hero_campus_url\":\"\\/video-bdtu\",\"identity_image\":\"assets\\/img\\/bb30a27931a9.jpg\",\"rector_profile_slug\":\"rector\",\"is_published\":true,\"created_at\":\"2026-07-22T13:24:57.000000Z\",\"updated_at\":\"2026-07-22T13:24:57.000000Z\",\"translations\":[{\"id\":4,\"about_page_id\":1,\"locale\":\"ar\",\"content\":{\"hero\":{\"badge\":\"\\u0631\\u064a\\u0627\\u062f\\u0629 \\u0641\\u064a \\u0627\\u0644\\u062a\\u0645\\u064a\\u0632 \\u0627\\u0644\\u0647\\u0646\\u062f\\u0633\\u064a\",\"title\":\"\\u062c\\u0627\\u0645\\u0639\\u0629 \\u0628\\u062e\\u0627\\u0631\\u0649 \\u0627\\u0644\\u062d\\u0643\\u0648\\u0645\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0629\",\"subtitle\":\"\\u062a\\u0623\\u0633\\u0633\\u062a \\u0628\\u0645\\u0648\\u062c\\u0628 \\u0627\\u0644\\u0645\\u0631\\u0633\\u0648\\u0645 \\u0627\\u0644\\u0631\\u0626\\u0627\\u0633\\u064a \\u0631\\u0642\\u0645 PP-22\\u060c \\u0648\\u062a\\u0645\\u062b\\u0644 \\u0627\\u0644\\u0642\\u0648\\u0629 \\u0627\\u0644\\u0623\\u0643\\u0627\\u062f\\u064a\\u0645\\u064a\\u0629 \\u0627\\u0644\\u0645\\u0648\\u062d\\u062f\\u0629 \\u0644\\u0644\\u0645\\u0624\\u0633\\u0633\\u0627\\u062a \\u0627\\u0644\\u062a\\u0642\\u0646\\u064a\\u0629 \\u0641\\u064a \\u0628\\u062e\\u0627\\u0631\\u0649. \\u062d\\u0627\\u0626\\u0632\\u0629 \\u0639\\u0644\\u0649 \\u0627\\u0644\\u0627\\u0633\\u062a\\u0642\\u0644\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0623\\u0643\\u0627\\u062f\\u064a\\u0645\\u064a\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0627\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0643\\u0627\\u0645\\u0644\\u0629 \\u0645\\u0646\\u0630 \\u0639\\u0627\\u0645 2026\\u060c \\u0644\\u0646\\u0635\\u0646\\u0639 \\u0645\\u0633\\u062a\\u0642\\u0628\\u0644\\u0627\\u064b \\u063