e \\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u0434\\u043b\\u044f \\u0433\\u043b\\u043e\\u0431\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u044d\\u043f\\u043e\\u0445\\u0438\",\"quote1\":\"\\u0414\\u043e\\u0431\\u0440\\u043e \\u043f\\u043e\\u0436\\u0430\\u043b\\u043e\\u0432\\u0430\\u0442\\u044c \\u0432 \\u0411\\u0443\\u0445\\u0430\\u0440\\u0441\\u043a\\u0438\\u0439 \\u0433\\u043e\\u0441\\u0443\\u0434\\u0430\\u0440\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0438\\u0442\\u0435\\u0442. \\u0412 2026 \\u0433\\u043e\\u0434\\u0443 \\u043d\\u0430\\u0448 \\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0438\\u0442\\u0435\\u0442 \\u043f\\u0435\\u0440\\u0435\\u0448\\u0435\\u043b \\u043d\\u0430 \\u043f\\u043e\\u043b\\u043d\\u0443\\u044e \\u0430\\u043a\\u0430\\u0434\\u0435\\u043c\\u0438\\u0447\\u0435\\u0441\\u043a\\u0443\\u044e \\u0438 \\u0444\\u0438\\u043d\\u0430\\u043d\\u0441\\u043e\\u0432\\u0443\\u044e \\u043d\\u0435\\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c, \\u0432\\u043d\\u0435\\u0434\\u0440\\u044f\\u044f \\u0443\\u0447\\u0435\\u0431\\u043d\\u044b\\u0435 \\u043f\\u043b\\u0430\\u043d\\u044b ECTS \\u043f\\u043e \\u0435\\u0432\\u0440\\u043e\\u043f\\u0435\\u0439\\u0441\\u043a\\u0438\\u043c \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u0430\\u043c. \\u041e\\u0431\\u044a\\u0435\\u0434\\u0438\\u043d\\u0438\\u0432 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442\\u044b, \\u043c\\u044b \\u0441\\u043e\\u0437\\u0434\\u0430\\u043b\\u0438 \\u043d\\u0430\\u0443\\u0447\\u043d\\u044b\\u0439 \\u0446\\u0435\\u043d\\u0442\\u0440.\",\"quote2\":\"\\u041c\\u044b \\u0432\\u0435\\u0440\\u0438\\u043c, \\u0447\\u0442\\u043e \\u043d\\u0430\\u0441\\u0442\\u043e\\u044f\\u0449\\u0430\\u044f \\u0438\\u043d\\u0436\\u0435\\u043d\\u0435\\u0440\\u0438\\u044f \\u043d\\u0435 \\u043c\\u043e\\u0436\\u0435\\u0442 \\u043f\\u0440\\u0435\\u043f\\u043e\\u0434\\u0430\\u0432\\u0430\\u0442\\u044c\\u0441\\u044f \\u0432 \\u043e\\u0442\\u0440\\u044b\\u0432\\u0435 \\u043e\\u0442 \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u043a\\u0438. \\u0418\\u043c\\u0435\\u043d\\u043d\\u043e \\u043f\\u043e\\u044d\\u0442\\u043e\\u043c\\u0443 \\u043d\\u0430\\u0448\\u0438 \\u0441\\u0442\\u0443\\u0434\\u0435\\u043d\\u0442\\u044b \\u0441\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u0447\\u0430\\u044e\\u0442 \\u0441 \\u0437\\u0430\\u0432\\u043e\\u0434\\u0430\\u043c\\u0438 \\u0438 \\u0443\\u0447\\u0430\\u0441\\u0442\\u0432\\u0443\\u044e\\u0442 \\u0432 \\u043f\\u0440\\u043e\\u0433\\u0440\\u0430\\u043c\\u043c\\u0430\\u0445 \\u0434\\u0432\\u043e\\u0439\\u043d\\u043e\\u0433\\u043e \\u0434\\u0438\\u043f\\u043b\\u043e\\u043c\\u0430 \\u0441 \\u041b\\u0430\\u0442\\u0432\\u0438\\u0435\\u0439, \\u0411\\u0435\\u043b\\u0430\\u0440\\u0443\\u0441\\u044c\\u044e \\u0438 \\u0422\\u0443\\u0440\\u0446\\u0438\\u0435\\u0439. \\u041c\\u044b \\u0433\\u043e\\u0442\\u043e\\u0432\\u0438\\u043c \\u044d\\u043b\\u0438\\u0442\\u0443 \\u0438\\u043d\\u0436\\u0435\\u043d\\u0435\\u0440\\u0438\\u0438.\",\"profileBtn\":\"\\u0411\\u0438\\u043e\\u0433\\u0440\\u0430\\u0444\\u0438\\u044f \\u0438 \\u0434\\u043e\\u0441\\u0442\\u0438\\u0436\\u0435\\u043d\\u0438\\u044f \\u0440\\u0435\\u043a\\u0442\\u043e\\u0440\\u0430\",\"appealBadge\":\"\\u041e\\u0441\\u043e\\u0431\\u043e\\u0435 \\u0432\\u043d\\u0438\\u043c\\u0430\\u043d\\u0438\\u0435\",\"appealTitle\":\"\\u0421\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435 \\u043e\\u0431\\u0440\\u0430\\u0449\\u0435\\u043d\\u0438\\u0435 \\u0440\\u0435\\u043a\\u0442\\u043e\\u0440\\u0430: \\u0417\\u0430\\u0449\\u0438\\u0442\\u0430 \\u043d\\u0430\\u0448\\u0435\\u0439 \\u043c\\u043e\\u043b\\u043e\\u0434\\u0435\\u0436\\u0438\",\"appealQuote\":\"\\u0421\\u0435\\u0433\\u043e\\u0434\\u043d\\u044f \\u0433\\u043b\\u043e\\u0431\\u0430\\u043b\\u044c\\u043d\\u044b