u0442\\u043e\\u044f\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442\",\"year1978Desc\":\"\\u0420\\u0435\\u043e\\u0440\\u0433\\u0430\\u043d\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u0432 \\u0411\\u0443\\u0445\\u0430\\u0440\\u0441\\u043a\\u0438\\u0439 \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442 \\u043f\\u0438\\u0449\\u0435\\u0432\\u043e\\u0439 \\u0438 \\u043b\\u0435\\u0433\\u043a\\u043e\\u0439 \\u043f\\u0440\\u043e\\u043c\\u044b\\u0448\\u043b\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0441 \\u043e\\u0442\\u043a\\u0440\\u044b\\u0442\\u0438\\u0435\\u043c \\u043d\\u043e\\u0432\\u044b\\u0445 \\u0445\\u0438\\u043c\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0445 \\u0438 \\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0445 \\u043a\\u0430\\u0444\\u0435\\u0434\\u0440.\",\"year2011Title\":\"\\u0410\\u043a\\u0430\\u0434\\u0435\\u043c\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u0440\\u0430\\u0441\\u0448\\u0438\\u0440\\u0435\\u043d\\u0438\\u0435 (\\u0411\\u0418\\u0422\\u0418)\",\"year2011Desc\":\"\\u042d\\u0432\\u043e\\u043b\\u044e\\u0446\\u0438\\u044f \\u0432 \\u0411\\u0443\\u0445\\u0430\\u0440\\u0441\\u043a\\u0438\\u0439 \\u0438\\u043d\\u0436\\u0435\\u043d\\u0435\\u0440\\u043d\\u043e-\\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442 (\\u0411\\u0418\\u0422\\u0418), \\u0441\\u043e\\u0437\\u0434\\u0430\\u043d\\u0438\\u0435 \\u043a\\u0440\\u0443\\u043f\\u043d\\u044b\\u0445 \\u043a\\u0430\\u0444\\u0435\\u0434\\u0440 \\u0430\\u0432\\u0442\\u043e\\u043c\\u0430\\u0442\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 \\u0438 \\u043d\\u0435\\u0444\\u0442\\u0435\\u0433\\u0430\\u0437\\u043e\\u0432\\u043e\\u0433\\u043e \\u0434\\u0435\\u043b\\u0430.\",\"year2025Title\":\"\\u0415\\u0434\\u0438\\u043d\\u044b\\u0439 \\u0411\\u0413\\u0422\\u0423 (\\u041f\\u043e\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u041f\\u041f-22)\",\"year2025Desc\":\"\\u041f\\u043e\\u0441\\u0442\\u0430\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435\\u043c \\u041f\\u0440\\u0435\\u0437\\u0438\\u0434\\u0435\\u043d\\u0442\\u0430 \\u2116 \\u041f\\u041f-22 \\u0411\\u0443\\u0445\\u0430\\u0440\\u0441\\u043a\\u0438\\u0439 \\u0438\\u043d\\u0436\\u0435\\u043d\\u0435\\u0440\\u043d\\u043e-\\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442 \\u0438 \\u0411\\u0443\\u0445\\u0430\\u0440\\u0441\\u043a\\u0438\\u0439 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442 \\u0443\\u043f\\u0440\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u043f\\u0440\\u0438\\u0440\\u043e\\u0434\\u043d\\u044b\\u043c\\u0438 \\u0440\\u0435\\u0441\\u0443\\u0440\\u0441\\u0430\\u043c\\u0438 \\u043e\\u0431\\u044a\\u0435\\u0434\\u0438\\u043d\\u0435\\u043d\\u044b \\u0432 \\u0411\\u0413\\u0422\\u0423.\",\"year2026Title\":\"\\u041f\\u043e\\u043b\\u043d\\u0430\\u044f \\u0430\\u0432\\u0442\\u043e\\u043d\\u043e\\u043c\\u0438\\u044f\",\"year2026Desc\":\"\\u0421 1 \\u044f\\u043d\\u0432\\u0430\\u0440\\u044f 2026 \\u0433\\u043e\\u0434\\u0430 \\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0438\\u0442\\u0435\\u0442\\u0443 \\u043f\\u0440\\u0435\\u0434\\u043e\\u0441\\u0442\\u0430\\u0432\\u043b\\u0435\\u043d\\u0430 \\u043f\\u043e\\u043b\\u043d\\u0430\\u044f \\u0430\\u043a\\u0430\\u0434\\u0435\\u043c\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f, \\u043e\\u0440\\u0433\\u0430\\u043d\\u0438\\u0437\\u0430\\u0446\\u0438\\u043e\\u043d\\u043d\\u0430\\u044f \\u0438 \\u0444\\u0438\\u043d\\u0430\\u043d\\u0441\\u043e\\u0432\\u0430\\u044f \\u043d\\u0435\\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c \\u0434\\u043b\\u044f \\u0443\\u0441\\u043a\\u043e\\u0440\\u0435\\u043d\\u0438\\u044f \\u0432\\u043d\\u0435\\u0434\\u0440\\u0435\\u043d\\u0438\\u044f \\u043c\\u0438\\u0440\\u043e\\u0432\\u044b\\u0445 \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043e\\u0432.\",\"infographicTitle\":\"\\u041e\\u0444\\u0438\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u0438\\u0441\\u0442\\u043e\\u0440\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u0438\\u043d\\u0444\\u043e\\u0433\\u0440\\u0430\\u0444\\u0438\\u043a\\u0430\",\"items\":[{\"year\":\"1959\",\"title\":\"\\u0412\\u0435\\u0447\\u0435\\u0440\\u043d\\u0435\\u0435 \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u043e\\u0442\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435\",\"desc\":\"\\u041e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0411\\u0443\\u0445\\u0430\\u0440\\u0441\\u043a\\u043e\\u0433\\u043e \\u0432\\u0435\\u0447\\u0435\\u0440\\u043d\\u0435\\u0433\\u043e \\u043e\\u0431\\u0449\\u0435\\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0433\\u043e \\u0444\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442\\u0430, \\u0437\\u0430\\u043b\\u043e\\u0436\\u0438\\u0432\\u0448\\u0435\\u0433\\u043e \\u043e\\u0441\\u043d\\u043e\\u0432\\u0443 \\u0438\\u043d\\u0436\\u0435\\u043d\\u0435\\u0440\\u043d\\u043e\\u0433\\u043e \\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u0432 \\u0411\\u0443\\u0445\\u0430\\u0440\\u0441\\u043a\\u043e\\u043c \\u043e\\u0430\\u0437\\u0438\\u0441\\u0435 \\u0434\\u043b\\u044f \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u0438 \\u043f\\u0440\\u043e\\u043c\\u044b\\u0448\\u043b\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438.\"},{\"year\":\"1978\",\"title\":\"\\u0421\\u0430\\u043c\\u043e\\u0441\\u0442\\u043e\\u044f\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442\",\"desc\":\"\\u0420\\u0435\\u043e\\u0440\\u0433\\u0430\\u043d\\u0438\\u043