3\\u0441\\u043a\\u043e\\u0440\\u0435\\u043d\\u0438\\u044f \\u0432\\u043d\\u0435\\u0434\\u0440\\u0435\\u043d\\u0438\\u044f \\u043c\\u0438\\u0440\\u043e\\u0432\\u044b\\u0445 \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043e\\u0432.\",\"infographicTitle\":\"\\u041e\\u0444\\u0438\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u0430\\u044f \\u0438\\u0441\\u0442\\u043e\\u0440\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u0438\\u043d\\u0444\\u043e\\u0433\\u0440\\u0430\\u0444\\u0438\\u043a\\u0430\",\"items\":[{\"year\":\"1959\",\"title\":\"\\u0412\\u0435\\u0447\\u0435\\u0440\\u043d\\u0435\\u0435 \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u043e\\u0442\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0435\",\"desc\":\"\\u041e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0411\\u0443\\u0445\\u0430\\u0440\\u0441\\u043a\\u043e\\u0433\\u043e \\u0432\\u0435\\u0447\\u0435\\u0440\\u043d\\u0435\\u0433\\u043e \\u043e\\u0431\\u0449\\u0435\\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0433\\u043e \\u0444\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442\\u0430, \\u0437\\u0430\\u043b\\u043e\\u0436\\u0438\\u0432\\u0448\\u0435\\u0433\\u043e \\u043e\\u0441\\u043d\\u043e\\u0432\\u0443 \\u0438\\u043d\\u0436\\u0435\\u043d\\u0435\\u0440\\u043d\\u043e\\u0433\\u043e \\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u0432 \\u0411\\u0443\\u0445\\u0430\\u0440\\u0441\\u043a\\u043e\\u043c \\u043e\\u0430\\u0437\\u0438\\u0441\\u0435 \\u0434\\u043b\\u044f \\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u0438 \\u043f\\u0440\\u043e\\u043c\\u044b\\u0448\\u043b\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438.\"},{\"year\":\"1978\",\"title\":\"\\u0421\\u0430\\u043c\\u043e\\u0441\\u0442\\u043e\\u044f\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0438\\u043d\\u0441\\u0442\\u0438\\u0442\\u0443\\u0442\",\"desc\":\"\\u0420\\u0435\\u043e\\u0440\\u0433\\u0430\\u043d\\u0438\\u043