INSERT INTO `audit_logs` (`id`, `user_id`, `action`, `model_type`, `model_id`, `old_values`, `new_values`, `ip_address`, `user_agent`, `created_at`) VALUES ('145', '1', 'update', 'App\\Models\\WebFooter', '1', '{\"id\":1,\"key\":\"main\",\"useful_links\":[{\"key\":\"home\",\"url\":\"\\/\"},{\"key\":\"about\",\"url\":\"\\/about\"},{\"key\":\"services\",\"url\":\"\\/services\"},{\"key\":\"contact\",\"url\":\"\\/contact\"}],\"faculty_links\":[{\"key\":\"engineering\",\"url\":\"\\/faculty\\/faculty-of-engineering\"},{\"key\":\"technology\",\"url\":\"\\/faculty\\/faculty-of-technology\"},{\"key\":\"natural\",\"url\":\"\\/faculty\\/faculty-of-natural-resources-management\"},{\"key\":\"service\",\"url\":\"\\/faculty\\/faculty-of-service-and-digitalization\"}],\"social_links\":[{\"key\":\"website\",\"label\":\"Website\",\"url\":\"https:\\/\\/www.bstu.uz\\/\"},{\"key\":\"telegram\",\"label\":\"Telegram\",\"url\":\"https:\\/\\/t.me\\/bdtu_uz_rasmiy\"},{\"key\":\"instagram\",\"label\":\"Instagram\",\"url\":\"https:\\/\\/www.instagram.com\\/bdtu.uz\"},{\"key\":\"youtube\",\"label\":\"YouTube\",\"url\":\"https:\\/\\/www.youtube.com\\/channel\\/UCzQe2GCCLZqa-aUItTAas2Q\"},{\"key\":\"facebook\",\"label\":\"Facebook\",\"url\":\"https:\\/\\/www.facebook.com\\/BDTU.UZ\"}],\"admissions_apply_url\":\"\\/apply\",\"phone\":\"+998 65 224 64 35\",\"email\":\"info@bstu.uz\",\"copyright_year\":2026,\"is_active\":true,\"created_at\":\"2026-07-16T12:36:10.000000Z\",\"updated_at\":\"2026-07-20T12:20:26.000000Z\",\"translations\":[{\"id\":1,\"web_footer_id\":1,\"locale\":\"en\",\"logo_alt\":\"BSTU\",\"description\":\"Bukhara State Technical University (BSTU) is a premier higher education and scientific research hub in Central Asia, preparing elite specialists in engineering and digital technologies.\",\"admissions_badge\":\"Admissions 2026\\/2027 Open\",\"admissions_heading\":\"Shape Your Future in Engineering & Technology\",\"admissions_description\":\"Join Bukhara State Technical University an