INSERT INTO `settings` (`id`, `key`, `value`, `type`, `group`, `is_public`, `created_at`, `updated_at`) VALUES ('45', 'pdf.admission.body', 'The student has submitted documents for studying at Bukhara State Technical University (Buxoro davlat texnika universiteti) in the Republic of Uzbekistan and has received an offer of enrollment in <b>{{program}}</b> program. The student will begin studies in the <b>{{academic_year}}</b> academic year at the first level <b>{{study_language}}-medium</b> program. The student must submit his/her original documents after arriving in the country.<br><br>The Ministry of Higher Education of the Republic of Uzbekistan recognizes Bukhara State Technical University (Buxoro davlat texnika universiteti). The university is listed in the Times Higher Education, QS World Rankings Asia 2025, UI GreenMetric World University Rankings.', 'text', 'pdf', '0', '2026-07-27 07:13:12', '2026-07-27 07:53:19');
