INSERT INTO `settings` (`id`, `key`, `value`, `type`, `group`, `is_public`, `created_at`, `updated_at`) VALUES ('47', 'pdf.admission.footer', 'This admission letter is generated by the university international admissions system. It is valid together with the applicant passport and original education documents.', 'text', 'pdf', '0', '2026-07-27 07:13:12', '2026-07-27 07:53:19');
INSERT INTO `settings` (`id`, `key`, `value`, `type`, `group`, `is_public`, `created_at`, `updated_at`) VALUES ('48', 'pdf.enrollment.title', 'ENROLLMENT CERTIFICATE', 'text', 'pdf', '0', '2026-07-27 07:13:12', '2026-07-27 07:53:19');
INSERT INTO `settings` (`id`, `key`, `value`, `type`, `group`, `is_public`, `created_at`, `updated_at`) VALUES ('49', 'pdf.enrollment.subtitle', 'Student Registration Confirmation', 'text', 'pdf', '0', '2026-07-27 07:13:12', '2026-07-27 07:53:19');
INSERT INTO `settings` (`id`, `key`, `value`, `type`, `group`, `is_public`, `created_at`, `updated_at`) VALUES ('50', 'pdf.enrollment.body', 'This is to certify that <b>{{name}}</b> has been enrolled as an international student of Bukhara State Technical University (Buxoro davlat texnika universiteti) for the <b>{{academic_year}}</b> academic year after receiving admission and completing the required initial contract payment. The student is registered in the <b>{{program}}</b> program.<br><br>This certificate is issued for submission to the relevant authorities and confirms the student registration status at the university as of the issue date above.', 'text', 'pdf', '0', '2026-07-27 07:13:12', '2026-07-27 07:53:19');
